import unittest

def add(a, b):
    return a + b

class TestAdd(unittest.TestCase):
    def test_int(self):
        self.assertEqual(add(2, 3), 5)

    def test_float(self):
        self.assertEqual(add(0.1, 0.2), 0.3)

    def helper(self):
        self.assertEqual(add(1, 1), 3)

if __name__ == "__main__":
    unittest.main()
